<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Plus,ArrowLeft,Download,MessageSquareText} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {validateReplies,importReplies,exportReplies,replyTriggers,scriptReport,type QuickReplySet} from './quick-replies'
const store=useLocal(),rows=ref<Document<QuickReplySet>[]>([]),bindings=ref<Document<{quickReplyIds:string[]}>|null>(null),editing=ref<QuickReplySet|null>(null),editingId=ref(''),revision=ref(0),search=ref(''),error=ref(''),busy=ref(false),controller=new AbortController();let disposed=false,epoch=0
const visible=computed(()=>rows.value.filter(row=>row.value.name.toLowerCase().includes(search.value.toLowerCase()))),labels={startup:'应用启动',session:'打开会话',user:'用户发送',assistant:'角色回复',member:'激活成员',manual:'手动'}
async function load(){const vault=store.vault;if(!vault)return;const [values,global]=await Promise.all([vault.list<QuickReplySet>('settings'),vault.read<{quickReplyIds:string[]}>('settings:quick-replies')]);if(disposed||store.vault!==vault)return;rows.value=values.filter(row=>row.value.assetType==='quick-replies');bindings.value=global}
function edit(row?:Document<QuickReplySet>){epoch++;editing.value=row?JSON.parse(JSON.stringify(row.value)):{assetType:'quick-replies',name:'新按钮组',enabled:true,policy:'fill',buttons:[]};editingId.value=row?.id||'quick-replies:'+crypto.randomUUID();revision.value=row?.revision||0;error.value=''}
function add(){editing.value!.buttons.push({id:crypto.randomUUID(),label:'新按钮',text:'',enabled:true,triggers:['manual']})}
async function commit(operation:string,id:string,expected:number,value:unknown){const vault=store.vault!;try{await vault.commitBundle(operation,[{kind:'settings',id,expectedRevision:expected,value}],controller.signal)}catch(e){if(controller.signal.aborted||store.vault!==vault||!vault.unlocked)throw e;const receipt=await vault.receipt(operation),saved=receipt?await vault.read(id):null;if(!saved||saved.revision!==expected+1||canonical(saved.value)!==canonical(value))throw e}}
async function save(){if(!store.vault||!editing.value||busy.value)return;busy.value=true;const generation=epoch,id=editingId.value,expected=revision.value,value=JSON.parse(JSON.stringify(editing.value)) as QuickReplySet;try{validateReplies(value);exportReplies(value);await commit(crypto.randomUUID(),id,expected,value);if(disposed||generation!==epoch)return;if(editing.value&&canonical(editing.value)!==canonical(value)){revision.value=expected+1;error.value='上一份修改已保存，当前内容还未保存'}else {editing.value=null;error.value=''};await load()}catch(e){if(!disposed&&generation===epoch)error.value=(e as Error).message}finally{busy.value=false}}
async function bind(row:Document<QuickReplySet>){if(!store.vault||busy.value)return;busy.value=true;try{const ids=bindings.value?.value.quickReplyIds||[],value={quickReplyIds:ids.includes(row.id)?ids.filter(id=>id!==row.id):[...ids,row.id]};await commit(crypto.randomUUID(),'settings:quick-replies',bindings.value?.revision||0,value);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement;if(!store.vault||busy.value)return;busy.value=true;const failures:string[]=[];try{const files=Array.from(input.files||[]);if(files.length>64)throw new Error('一次最多导入 64 组按钮');for(const file of files){controller.signal.throwIfAborted();try{if(file.size>2*1024*1024)throw new Error('按钮组超过 2 MiB');const value=importReplies(await file.text());exportReplies(value);await commit(crypto.randomUUID(),'quick-replies:'+crypto.randomUUID(),0,value)}catch(e){if(controller.signal.aborted)throw e;failures.push(file.name+'：'+(e as Error).message)}}await load();error.value=failures.join('；')}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
function download(row:Document<QuickReplySet>){try{const url=URL.createObjectURL(new Blob([exportReplies(row.value)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.value.name+'.qr.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
function report(text:string){try{const value=scriptReport(text);return value.unsupported.length?'未支持：'+value.unsupported.join('、'):value.commands.length?value.commands.map(value=>'/'+value).join(' → '):'填入草稿'}catch(e){return (e as Error).message}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;controller.abort()})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">QUICK REPLIES</span><h1>{{editing?editing.name:'快捷按钮'}}</h1></div><div class="final-page-actions"><button v-if="editing" @click="epoch++;editing=null"><ArrowLeft :size="18"/>返回</button><button v-else class="final-primary" @click="edit()"><Plus :size="18"/>新建</button></div></div><p v-if="error" role="alert" class="final-error">{{error}}</p><form v-if="editing" class="final-card-form" @submit.prevent="save"><label>按钮组名称<input v-model="editing.name" maxlength="200" required></label><label>执行方式<select aria-label="执行方式" v-model="editing.policy"><option value="fill">填入草稿</option><option value="confirm">确认后执行</option><option value="compat">兼容执行</option><option value="disabled">停用</option></select></label><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用按钮组</label><article v-for="button in editing.buttons" :key="button.id" class="final-import-panel"><label>按钮名称<input v-model="button.label" maxlength="200" required></label><label>正文或脚本<textarea v-model="button.text" maxlength="50000" rows="4" spellcheck="false"></textarea></label><small class="final-subtle">{{report(button.text)}}</small><label class="final-check"><input v-model="button.enabled" type="checkbox">启用按钮</label><div class="final-grid-actions"><label v-for="trigger in replyTriggers" :key="trigger" class="final-check"><input v-model="button.triggers" :value="trigger" type="checkbox">{{labels[trigger]}}</label></div><button type="button" @click="editing.buttons=editing.buttons.filter(row=>row.id!==button.id)">移除按钮</button></article><button type="button" :disabled="editing.buttons.length>=32" @click="add">添加按钮</button><button class="final-primary" :disabled="busy">保存按钮组</button><details v-if="editing.source"><summary>保留的原始格式</summary><pre class="final-task-prose">{{editing.source}}</pre></details></form><template v-else><div class="final-page-actions"><RouterLink to="/local/characters" class="final-text-link">返回角色</RouterLink><RouterLink to="/local/tavern/presets" class="final-text-link">提示预设</RouterLink></div><label class="final-import-panel">导入快捷按钮<input type="file" multiple accept=".json" :disabled="busy" @change="upload"></label><label v-if="rows.length" class="final-search">搜索按钮组<input v-model="search" type="search"></label><div v-if="!rows.length" class="final-empty"><MessageSquareText :size="40"/><h2>把常用动作放在手边</h2><button class="final-primary" @click="edit()">创建按钮组</button></div><div class="final-collection-grid"><article v-for="row in visible" :key="row.id" class="final-character-card"><MessageSquareText :size="28"/><h2>{{row.value.name}}</h2><small>{{row.value.buttons.length}} 个按钮 · 版本 {{row.revision}}</small><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button class="final-icon-button" :aria-label="'导出按钮组'+row.value.name" @click="download(row)"><Download :size="18"/></button></div><button :disabled="busy" :aria-pressed="!!bindings?.value.quickReplyIds.includes(row.id)" @click="bind(row)">{{bindings?.value.quickReplyIds.includes(row.id)?'移除全局绑定':'绑定所有对话'}}</button></article></div></template></section></template>
